// tools/layoutpatch/torque-lite.mjs
//
// A deliberately small Torque reader. It answers exactly one question:
//
//   what fields does `extern class X` declare, in declaration order, and under
//   what condition / with what element count?
//
// It exists because profiles/<tag>/layouts.json -- generated by
// tools/profilegen -- silently drops Torque fields whose index or condition
// expression contains a call form (`Convert<intptr>(x)`,
// `FromConstexpr<T>(T::K)`). For ScopeInfo that is three fields, including
// `context_local_names`, which is where real variable names live. Dropping an
// interior field does not just lose data: it shifts every later field, so the
// layout program in layouts.json decodes ScopeInfo incorrectly whenever those
// fields are present.
//
// This reader is NOT a Torque implementation. It handles the subset the object
// layout files use and refuses anything else, so a future syntax change fails
// loudly instead of producing a plausible wrong layout.
//
// Expression ASTs are emitted in exactly the shape layouts.json uses
// (`name` / `member` / `binary` / `ternary` / `literal` / `enumRef`) so the
// consumer needs one evaluator, not two.

/** Strip // and /* *\/ comments without touching string literals. */
export function stripComments(src) {
  let out = '';
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (c === '/' && src[i + 1] === '/') { while (i < src.length && src[i] !== '\n') i++; out += '\n'; continue; }
    if (c === '/' && src[i + 1] === '*') { i += 2; while (i < src.length && !(src[i] === '*' && src[i + 1] === '/')) i++; i++; continue; }
    if (c === "'" || c === '"') { const q = c; out += c; i++; while (i < src.length && src[i] !== q) { out += src[i]; i++; } out += q; continue; }
    out += c;
  }
  return out;
}

// --------------------------------------------------------------- expressions

const TOKEN_RE = /\s*(::|==|!=|<=|>=|&&|\|\||[A-Za-z_]\w*|0x[0-9a-fA-F]+|\d+|[<>?:().,{}\[\]+*\-\/])/g;

function tokenize(text) {
  const toks = [];
  TOKEN_RE.lastIndex = 0;
  let m;
  let pos = 0;
  while ((m = TOKEN_RE.exec(text))) {
    if (m.index !== pos && text.slice(pos, m.index).trim() !== '') {
      throw new Error(`torque-lite: cannot tokenise ${JSON.stringify(text.slice(pos, m.index + m[0].length))}`);
    }
    toks.push(m[1]);
    pos = TOKEN_RE.lastIndex;
  }
  if (text.slice(pos).trim() !== '') throw new Error(`torque-lite: trailing junk ${JSON.stringify(text.slice(pos))}`);
  return toks;
}

/**
 * Parse one Torque expression.
 *
 * Supported: identifiers, `a.b`, `Enum::MEMBER`, integer literals,
 * `==` `!=` `<` `<=` `>` `>=`, `? :`, parentheses and generic call forms.
 *
 * Generic call forms are unwrapped to their single argument:
 *   Convert<intptr>(x)                        -> x
 *   FromConstexpr<VariableAllocationInfo>(V)  -> V
 * Both are representation casts in Torque: they change the static type, never
 * the value, so the layout arithmetic is identical. That is the one semantic
 * assumption in this file and it is asserted by the cross-check in index.mjs,
 * which requires every field layouts.json *does* carry to come out identical.
 */
export function parseExpression(text) {
  const toks = tokenize(text);
  let i = 0;
  const peek = () => toks[i];
  const take = (t) => {
    if (t !== undefined && toks[i] !== t) throw new Error(`torque-lite: expected ${t}, got ${toks[i]} in ${JSON.stringify(text)}`);
    return toks[i++];
  };

  function primary() {
    const t = peek();
    if (t === undefined) throw new Error(`torque-lite: unexpected end of ${JSON.stringify(text)}`);
    if (t === '(') { take('('); const e = ternary(); take(')'); return e; }
    if (/^(0x[0-9a-fA-F]+|\d+)$/.test(t)) { take(); return { kind: 'literal', value: Number(t) }; }
    if (/^[A-Za-z_]\w*$/.test(t)) {
      let name = take();
      // generic argument list of a call form: Name<T>(arg) / Name<A<B>>(arg)
      if (peek() === '<') {
        const save = i;
        let depth = 0;
        const generic = [];
        while (i < toks.length) {
          const g = toks[i];
          i++;
          if (g === '<') { depth++; if (depth === 1) continue; }
          else if (g === '>') { depth--; if (depth === 0) break; }
          generic.push(g);
        }
        if (depth !== 0 || peek() !== '(') { i = save; } // a comparison, not a call form
        else {
          take('(');
          const arg = ternary();
          take(')');
          return { kind: 'cast', castTo: generic.join(''), via: name, expr: arg };
        }
      }
      if (peek() === '(') { take('('); const arg = ternary(); take(')'); return { kind: 'cast', castTo: null, via: name, expr: arg }; }
      if (peek() === '::') { take('::'); const member = take(); return { kind: 'enumRef', enum: name, member }; }
      let node = { kind: 'name', name };
      while (peek() === '.') { take('.'); node = { kind: 'member', object: node, field: take() }; }
      return node;
    }
    throw new Error(`torque-lite: unexpected token ${t} in ${JSON.stringify(text)}`);
  }

  const COMPARE = new Set(['==', '!=', '<', '<=', '>', '>=']);
  function compare() {
    let left = primary();
    while (COMPARE.has(peek())) {
      const op = take();
      const right = primary();
      left = { kind: 'binary', op, left, right };
    }
    return left;
  }

  function ternary() {
    const cond = compare();
    if (peek() !== '?') return cond;
    take('?');
    const then = ternary();
    take(':');
    const els = ternary();
    return { kind: 'ternary', cond, then, else: els };
  }

  const e = ternary();
  if (i !== toks.length) throw new Error(`torque-lite: unconsumed tokens in ${JSON.stringify(text)}`);
  return e;
}

/** Drop `cast` wrappers, which are type-only in Torque. */
export function unwrapCasts(node) {
  if (!node || typeof node !== 'object') return node;
  if (node.kind === 'cast') return unwrapCasts(node.expr);
  const out = { ...node };
  for (const k of ['left', 'right', 'cond', 'then', 'else', 'object', 'expr']) {
    if (out[k] && typeof out[k] === 'object') out[k] = unwrapCasts(out[k]);
  }
  return out;
}

// --------------------------------------------------------------- declarations

/** `const kFoo: constexpr int32 generates 'kBar';` -> {kFoo: 'kBar'} */
export function parseGeneratesConsts(src) {
  const out = {};
  const re = /const\s+(\w+)\s*:\s*constexpr\s+[\w:]+\s*generates\s*'([^']+)'/g;
  let m;
  while ((m = re.exec(src))) out[m[1]] = m[2];
  return out;
}

/** `extern enum Name extends base { A, B }` -> ordinal map (declaration order). */
export function parseTorqueEnums(src) {
  const out = {};
  const re = /(?:extern\s+)?enum\s+(\w+)(?:\s+extends\s+([\w:]+))?\s*\{([^}]*)\}/g;
  let m;
  while ((m = re.exec(src))) {
    const [, name, base, body] = m;
    const members = {};
    let next = 0;
    for (const raw of body.split(',')) {
      const t = raw.trim();
      if (!t || t === '...') continue;
      const em = /^(\w+)(?:\s*=\s*(-?\w+))?$/.exec(t);
      if (!em) continue;
      next = em[2] !== undefined ? Number(em[2]) : next;
      members[em[1]] = next;
      next++;
    }
    out[name] = { name, base: base ?? null, members };
  }
  return out;
}

/** `struct Name { f: T; ... }` -> field type list (sizes resolved by the caller). */
export function parseTorqueStructs(src) {
  const out = {};
  const re = /(?:^|\n)\s*struct\s+(\w+)\s*\{([\s\S]*?)\n\}/g;
  let m;
  while ((m = re.exec(src))) {
    const fields = [];
    for (const line of m[2].split(';')) {
      const fm = /^\s*(\w+)\s*:\s*([^;]+)$/.exec(line);
      if (fm) fields.push({ name: fm[1], type: fm[2].trim().replace(/\s+/g, ' ') });
    }
    out[m[1]] = { name: m[1], fields };
  }
  return out;
}

/**
 * Parse `extern class <Name> extends <Parent> { ... }` bodies.
 *
 * Returns, per class, the declared fields in order with:
 *   name, type, annotations, conditionExpr (from `?[expr]`),
 *   countExpr (from `[expr]`), indexed, conditional
 */
export function parseTorqueClasses(src) {
  const text = stripComments(src);
  const classes = {};
  const re = /(?:^|\n)((?:\s*@[\w()\s,.<>!=|&:'"-]*\n)*)\s*(extern\s+)?class\s+(\w+)\s+extends\s+([\w:]+)\s*\{/g;
  let m;
  while ((m = re.exec(text))) {
    const [, annText, , name, parent] = m;
    // find the matching close brace
    let depth = 1;
    let i = re.lastIndex;
    while (i < text.length && depth > 0) {
      if (text[i] === '{') depth++;
      else if (text[i] === '}') depth--;
      i++;
    }
    const body = text.slice(re.lastIndex, i - 1);
    classes[name] = {
      name,
      parent,
      annotations: (annText.match(/@[\w]+/g) ?? []).map((a) => a.slice(1)),
      fields: parseClassBody(body, name),
    };
  }
  return classes;
}

function splitTopLevel(body) {
  // Split on ';' that is not nested inside (), [] or {}, and also at the '}'
  // that closes a top-level block. The second rule matters: a method *with a
  // body* is not ';'-terminated, so without it the body runs on into the next
  // declaration and takes the following field with it --
  //
  //   extern class ConsString extends String {
  //     macro IsFlat(): bool { return this.second.length == 0; }
  //     first: String;        <- swallowed by the macro's statement
  //     second: String;
  //   }
  //
  // which cost this reader `ConsString.first`, `String.length` and
  // `Map.instance_size_in_words` until the cross-check was widened from
  // ScopeInfo to every class and profilegen's reader disagreed.
  //
  // Angle brackets are deliberately NOT tracked: Torque uses '<' both for
  // generic arguments and as a comparison operator inside index expressions
  // (`context_local_names[Convert<intptr>(n) < kMax ? n : 0]`), so a depth
  // counter over '<' never returns to zero. A ';' never occurs inside a
  // generic argument list, so ignoring them is safe.
  const parts = [];
  let cur = '';
  let round = 0, square = 0, curly = 0;
  for (const c of body) {
    if (c === '(') round++;
    else if (c === ')') round--;
    else if (c === '[') square++;
    else if (c === ']') square--;
    else if (c === '{') curly++;
    else if (c === '}') {
      curly--;
      cur += c;
      if (curly === 0) { parts.push(cur); cur = ''; }
      continue;
    }
    if (c === ';' && !round && !square && !curly) { parts.push(cur); cur = ''; continue; }
    cur += c;
  }
  if (cur.trim()) parts.push(cur);
  return parts;
}

function parseClassBody(body, className) {
  const fields = [];
  for (const rawDecl of splitTopLevel(body)) {
    const decl = rawDecl.trim();
    if (!decl) continue;

    // leading annotations
    const annotations = [];
    let rest = decl;
    for (;;) {
      const am = /^@(\w+)(\([^)]*\))?\s*/.exec(rest);
      if (!am) break;
      annotations.push({ name: am[1], arg: am[2] ? am[2].slice(1, -1) : null });
      rest = rest.slice(am[0].length);
    }
    const km = /^(const|weak)\s+/.exec(rest);
    const qualifiers = [];
    if (km) { qualifiers.push(km[1]); rest = rest.slice(km[0].length); }

    // Per src/torque/torque-parser.cc `Symbol classField`, a field is
    //   name ('?')? ('[' expr ']')? ':' type
    // so what follows the name decides. '(' or '<' starts a macro / operator
    // signature and '{' starts a body; anything else must parse as a field.
    // Deciding on "does the statement contain a '('" instead is what made
    // profilegen drop three ScopeInfo fields, because an index expression
    // contains a cast call.
    const lead = /^(\w+)\s*(.?)/.exec(rest);
    if (!lead) throw new Error(`torque-lite: ${className}: cannot parse declaration ${JSON.stringify(decl)}`);
    if (lead[2] === '(' || lead[2] === '<' || lead[2] === '{') continue;   // macro / operator / method

    const fm = /^(\w+)\s*(\?)?\s*(\[([\s\S]*)\])?\s*:\s*([\s\S]+)$/.exec(rest);
    if (!fm) throw new Error(`torque-lite: ${className}: cannot parse declaration ${JSON.stringify(decl)}`);
    const [, name, question, , bracket, type] = fm;
    const conditional = question === '?';
    const indexed = bracket !== undefined && !conditional;
    fields.push({
      name,
      type: type.trim().replace(/\s+/g, ' '),
      annotations,
      qualifiers,
      conditional,
      indexed,
      conditionExpr: conditional ? bracket.trim().replace(/\s+/g, ' ') : null,
      countExpr: indexed ? bracket.trim().replace(/\s+/g, ' ') : null,
    });
  }
  return fields;
}

// ------------------------------------------------------------------ C++ enums

/**
 * `enum class Name : type { A, B = 3, ... };` -> ordinal map.
 * Entries whose initialiser aliases another member (`kLast = kFoo`) are kept
 * as aliases rather than advancing the counter, which is how C++ behaves.
 */
export function parseCppEnum(src, enumName) {
  const text = stripComments(src);
  const re = new RegExp(`enum\\s+(?:class\\s+)?${enumName}\\s*(?::\\s*[\\w:]+\\s*)?\\{`, 'g');
  const m = re.exec(text);
  if (!m) return null;
  let depth = 1, i = re.lastIndex;
  while (i < text.length && depth > 0) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}') depth--;
    i++;
  }
  const body = text.slice(re.lastIndex, i - 1);
  const members = {};
  const aliases = {};
  let next = 0;
  for (const raw of body.split(',')) {
    const t = raw.trim();
    if (!t) continue;
    const em = /^(\w+)(?:\s*=\s*([^,]+))?$/.exec(t);
    if (!em) continue;
    const [, name, init] = em;
    if (init === undefined) { members[name] = next++; continue; }
    const lit = /^-?(0x[0-9a-fA-F]+|\d+)$/.exec(init.trim());
    if (lit) { next = Number(init.trim()); members[name] = next; next++; continue; }
    const ref = init.trim();
    if (members[ref] !== undefined) { aliases[name] = ref; continue; }
    throw new Error(`torque-lite: ${enumName}: cannot evaluate initialiser ${JSON.stringify(init)} for ${name}`);
  }
  return { name: enumName, members, aliases };
}

/**
 * `inline bool IsFoo(FunctionKind kind) { return base::IsInRange(kind, A, B) || ...; }`
 * -> [[A, B], ...] as member-name pairs, plus equality forms
 * `kind == FunctionKind::kX` -> [[kX, kX]].
 *
 * Any predicate body with a form this does not understand is reported rather
 * than approximated.
 */
export function parseIsInRangePredicates(src, enumName) {
  const text = stripComments(src);
  const out = {};
  const re = new RegExp(`inline\\s+bool\\s+(\\w+)\\s*\\(\\s*${enumName}\\s+\\w+\\s*\\)\\s*\\{`, 'g');
  let m;
  while ((m = re.exec(text))) {
    const predName = m[1];
    let depth = 1, i = re.lastIndex;
    while (i < text.length && depth > 0) {
      if (text[i] === '{') depth++;
      else if (text[i] === '}') depth--;
      i++;
    }
    const body = text.slice(re.lastIndex, i - 1).replace(/\s+/g, ' ');
    const ranges = [];
    let understood = true;
    let remainder = body.replace(/^\s*return\s*/, '').replace(/;\s*$/, '');
    const rangeRe = new RegExp(`base::IsInRange\\(\\s*\\w+\\s*,\\s*${enumName}::(\\w+)\\s*,\\s*${enumName}::(\\w+)\\s*\\)`, 'g');
    let r;
    while ((r = rangeRe.exec(remainder))) ranges.push([r[1], r[2]]);
    remainder = remainder.replace(rangeRe, '');
    const eqRe = new RegExp(`\\w+\\s*==\\s*${enumName}::(\\w+)`, 'g');
    let e;
    while ((e = eqRe.exec(remainder))) ranges.push([e[1], e[1]]);
    remainder = remainder.replace(eqRe, '');
    // what is left must be only disjunction glue
    if (remainder.replace(/[\s|()]/g, '') !== '') understood = false;
    out[predName] = { ranges, understood, body: understood ? undefined : body };
  }
  return out;
}

export default {
  stripComments, parseExpression, unwrapCasts, parseGeneratesConsts,
  parseTorqueEnums, parseTorqueStructs, parseTorqueClasses, parseCppEnum,
  parseIsInRangePredicates,
};
